    function __ESBMC_assume(bool) internal pure {}
    function run(uint initial) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (initial) + (0)); require(initial <= 1000000000000000000000000000000);
        require(initial > 0);
        require(address(this).balance >= initial);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: initial}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        c.Deposit{value: 0}(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == balBefore && address(c).balance == ethBefore);
    }
    receive() external payable {}
